stereotypeDefinition.onAppliedScript:
function execute(element) {
    const auditTableStereotypeId = "c90080ae-bf89-4d10-b398-759e07630f98";
    let package = element.getPackage();
    let auditTables = package.getChildren(element.specialization).filter(x => x.hasStereotype(auditTableStereotypeId));
    auditTables.forEach(at => {
        if (at !== undefined && at !== null && at.getName() != element.getName()) {
            at.delete();
        }
    });
    if (element.hasStereotype(auditTableStereotypeId)) {
        ensureAttributes(element, true);
    }
    else {
        removeAttribute(element, "Id");
        removeAttribute(element, "PartitionKey");
        removeAttribute(element, "Payload");
        removeAttribute(element, "PayloadHash");
        removeAttribute(element, "Kind");
        removeAttribute(element, "Name");
        removeAttribute(element, "DurationMs");
        removeAttribute(element, "Status");
        removeAttribute(element, "Error");
        removeAttribute(element, "TraceId");
        removeAttribute(element, "UserId");
        removeAttribute(element, "CreatedAt");
    }
}
function ensureAttributes(element, enforceFieldTypes) {
    const dateTimeOffsetTypeId = "f1ba4df3-a5bc-427e-a591-4f6029f89bd7";
    const stringTypeId = "d384db9c-a279-45e1-801e-e4e8099625f2";
    const intTypeId = "fb0a362d-e9e2-40de-b6ff-5ce8167cbe74";
    const guidTypeId = "6b649125-18ea-48fd-a6ba-0bfff0d8f488";
    ensureAttribute(element, guidTypeId, false, "Id", enforceFieldTypes);
    ensureAttribute(element, stringTypeId, false, "PartitionKey", enforceFieldTypes);
    ensureAttribute(element, stringTypeId, false, "Payload", enforceFieldTypes);
    ensureAttribute(element, stringTypeId, false, "PayloadHash", enforceFieldTypes);
    ensureAttribute(element, stringTypeId, false, "Kind", enforceFieldTypes);
    ensureAttribute(element, stringTypeId, false, "Name", enforceFieldTypes);
    ensureAttribute(element, intTypeId, false, "DurationMs", enforceFieldTypes);
    ensureAttribute(element, stringTypeId, false, "Status", enforceFieldTypes);
    ensureAttribute(element, stringTypeId, false, "Error", enforceFieldTypes);
    ensureAttribute(element, stringTypeId, false, "TraceId", enforceFieldTypes);
    ensureAttribute(element, guidTypeId, false, "UserId", enforceFieldTypes);
    ensureAttribute(element, dateTimeOffsetTypeId, false, "CreatedAt", enforceFieldTypes, "DateTimeOffset.UtcNow");
}
function ensureAttribute(element, typeId, isNullable, name, enforceFieldType, value) {
    let el = element.getChildren("Attribute").filter(x => x.getName() == name)[0];
    if (el == null) {
        el = createElement("Attribute", name, element.id);
        el.setMetadata("set-by-infrastructure", "true");
        el.typeReference.setIsNullable(isNullable);
        el.typeReference.setType(typeId);
    }
    if (enforceFieldType) {
        el.typeReference.setIsNullable(isNullable);
        el.typeReference.setType(typeId);
        el.typeReference.setValue(value);
    }
}
function removeAttribute(element, name) {
    let el = element.getChildren("Attribute").filter(x => x.getName() == name)[0];
    if (el == null || !el.hasMetadata("set-by-infrastructure")) {
        return;
    }
    el.delete();
}
execute(element);

